311	static char *next_string(struct sk_buff *skb)
312	{
313		int i = 0;
314		char *this = skb->data;
315		
316		for (i = 0; i < skb->len; i++) {
317			if (this[i] == '\n') {
318				this[i] = 0;
319				skb_pull(skb, i + 1);
320				return this;
321			}
322			if (!isprint(this[i]))
