182:static inline void rxe_rcv_pkt(struct rxe_pkt_info *pkt, struct sk_buff *skb)
183:{
184:	if (pkt->mask & RXE_REQ_MASK)
185:		rxe_resp_queue_pkt(pkt->qp, skb);
186:	else
187:		rxe_comp_queue_pkt(pkt->qp, skb);
