316:void rxe_rcv(struct sk_buff *skb)
317:{
318:	int err;
319:	struct rxe_pkt_info *pkt = SKB_TO_PKT(skb);
320:	struct rxe_dev *rxe = pkt->rxe;
321:	unsigned int skblen = skb->len - skb_network_offset(skb);
322:
323:	if (unlikely(skb->len < RXE_BTH_BYTES))
324:		goto drop;
325:
326:	if (rxe_chk_dgid(rxe, skb) < 0)
327:		goto drop;
328:
329:	pkt->opcode = bth_opcode(pkt);
330:	pkt->psn = bth_psn(pkt);
331:	pkt->qp = NULL;
332:	pkt->mask |= rxe_opcode[pkt->opcode].mask;
333:
334:	/*
335:	 * Unknown opcodes have a zero-initialized rxe_opcode[] entry, so
336:	 * both mask and length are 0.  Reject them before any length math:
337:	 * rxe_icrc_hdr() would otherwise compute length - RXE_BTH_BYTES
338:	 * and pass the underflowed value to rxe_crc32(), producing an
339:	 * out-of-bounds read.
340:	 */
341:	if (unlikely(!rxe_opcode[pkt->opcode].mask ||
342:		     !rxe_opcode[pkt->opcode].length))
343:		goto drop;
344:
345:	if (unlikely(pkt->paylen < header_size(pkt) + bth_pad(pkt) +
346:		       RXE_ICRC_SIZE))
347:		goto drop;
348:
349:	err = hdr_check(pkt);
350:	if (unlikely(err))
351:		goto drop;
352:
353:	err = rxe_icrc_check(skb, pkt);
354:	if (unlikely(err))
355:		goto drop;
356:
357:	rxe_counter_add(rxe, RXE_CNT_RCVD_BYTES, skblen);
358:	rxe_counter_inc(rxe, RXE_CNT_RCVD_PKTS);
359:
360:	if (unlikely(bth_qpn(pkt) == IB_MULTICAST_QPN))
361:		rxe_rcv_mcast_pkt(rxe, skb);
362:	else
363:		rxe_rcv_pkt(pkt, skb);
364:
365:	return;
366:
367:drop:
368:	if (pkt->qp)
369:		rxe_put(pkt->qp);
370:
371:	kfree_skb(skb);
372:	ib_device_put(&rxe->ib_dev);
373:}

