	else
		err = rxe_send(skb, pkt);
	if (err) {
		rxe_counter_inc(rxe, RXE_CNT_SEND_ERR);
		return err;
	}

	rxe_counter_inc(rxe, RXE_CNT_SENT_PKTS);
	rxe_counter_add(rxe, RXE_CNT_SENT_BYTES, skblen);
